INSERT INTO authors (name, bio) VALUES
                                    ('J.K. Rowling', 'Britská spisovateľka, najznámejšia svojou sériou kníh o Harrym Potterovi.'),
                                    ('George R.R. Martin', 'Americký spisovateľ fantasy, hororu a sci-fi, najznámy svojou sériou A Song of Ice and Fire.'),
                                    ('Agatha Christie', 'Britská spisovateľka detektívok, jedna z najpredávanejších autorov vôbec.'),
                                    ('George Orwell', 'Britský spisovateľ a novinár, známy dielami 1984 a Farma zvierat.'),
                                    ('Jane Austen', 'Britská spisovateľka známa romantickými románmi ako Pýcha a predsudok.'),
                                    ('Mark Twain', 'Americký spisovateľ a humorista, autor Dobrodružstiev Huckleberryho Finna.'),
                                    ('Ernest Hemingway', 'Americký spisovateľ, nositeľ Nobelovej ceny, známy dielom Starec a more.'),
                                    ('F. Scott Fitzgerald', 'Americký autor známy románom Veľký Gatsby.'),
                                    ('Leo Tolstoy', 'Ruský spisovateľ, autor diel Vojna a mier a Anna Karenina.'),
                                    ('Fyodor Dostoevsky', 'Ruský spisovateľ známy psychologickými románmi ako Zločin a trest.'),
                                    ('Charles Dickens', 'Britský spisovateľ, autor Olivera Twista a Vianočnej koledy.'),
                                    ('Virginia Woolf', 'Britská modernistická spisovateľka, známa dielom Pani Dallowayová.'),
                                    ('Agatha Christie', 'Britská autorka detektívok, tvorca postáv Hercule Poirot a Miss Marple.'),
                                    ('Stephen King', 'Americký autor hororov, známy knihami ako To a Osvietenie.'),
                                    ('J.R.R. Tolkien', 'Britský spisovateľ, autor Pána prsteňov.'),
                                    ('George R.R. Martin', 'Americký autor fantasy série Pieseň ľadu a ohňa.'),
                                    ('Haruki Murakami', 'Japonský spisovateľ známy surrealistickými románmi.'),
                                    ('Paulo Coelho', 'Brazílsky autor, známy knihou Alchymista.'),
                                    ('Dan Brown', 'Americký spisovateľ, autor thrillerov ako Da Vinciho kód.'),
                                    ('Khaled Hosseini', 'Afgansko-americký autor známy knihou Lovec šarkanov.'),
                                    ('Suzanne Collins', 'Americká autorka série Hry o život.'),
                                    ('J.D. Salinger', 'Americký spisovateľ, autor románu Kto chytá v žite.'),
                                    ('Herman Melville', 'Americký autor známy dielom Moby Dick.'),
                                    ('Oscar Wilde', 'Írsky dramatik a spisovateľ, autor Obrazu Doriana Graya.'),
                                    ('Victor Hugo', 'Francúzsky spisovateľ, autor Bedárov.'),
                                    ('Alexandre Dumas', 'Francúzsky autor známy Tromi mušketiermi.'),
                                    ('Franz Kafka', 'Pražský nemecky píšuci autor, známy dielom Proces.'),
                                    ('Gabriel García Márquez', 'Kolumbijský autor, predstaviteľ magického realizmu.'),
                                    ('Isabel Allende', 'Čilská spisovateľka známa románom Dom duchov.'),
                                    ('Albert Camus', 'Francúzsky filozof a spisovateľ, autor Cudzinca.'),
                                    ('Jean-Paul Sartre', 'Francúzsky filozof a spisovateľ, predstaviteľ existencializmu.'),
                                    ('H.G. Wells', 'Britský autor sci-fi, známy dielom Vojna svetov.'),
                                    ('Arthur Conan Doyle', 'Britský autor, tvorca Sherlocka Holmesa.'),
                                    ('Bram Stoker', 'Írsky spisovateľ, autor románu Dracula.'),
                                    ('Mary Shelley', 'Britská autorka, známa románom Frankenstein.'),
                                    ('Emily Brontë', 'Britská spisovateľka, autorka Búrlivých výšin.'),
                                    ('Charlotte Brontë', 'Britská autorka románu Jana Eyrová.'),
                                    ('Louisa May Alcott', 'Americká autorka známa románom Malé ženy.'),
                                    ('Jack London', 'Americký spisovateľ, autor Volania divočiny.'),
                                    ('Jules Verne', 'Francúzsky autor sci-fi, známy dielom Cesta do stredu Zeme.'),
                                    ('Miguel de Cervantes', 'Španielsky autor románu Don Quijote.'),
                                    ('Dante Alighieri', 'Taliansky básnik, autor Božskej komédie.'),
                                    ('Homer', 'Starogrécky epický básnik, autor Iliady a Odysey.'),
                                    ('William Shakespeare', 'Anglický dramatik a básnik, autor Hamleta a Rómea a Júlie.'),
                                    ('Terry Pratchett', 'Britský autor fantasy série Zeměplocha.'),
                                    ('Neil Gaiman', 'Britský autor fantasy a komiksov.'),
                                    ('Margaret Atwood', 'Kanadská spisovateľka známa románom Príbeh služobníčky.'),
                                    ('Cormac McCarthy', 'Americký autor známy temnými románmi ako Cesta.'),
                                    ('Kazuo Ishiguro', 'Britský autor japonského pôvodu, nositeľ Nobelovej ceny.'),
                                    ('Salman Rushdie', 'Britsko-indický spisovateľ známy románom Satanské verše.'),
                                    ('Umberto Eco', 'Taliansky autor a filozof, známy románom Meno ruže.'),
                                    ('Orhan Pamuk', 'Turecký spisovateľ, nositeľ Nobelovej ceny.'),
                                    ('Elena Ferrante', 'Talianska autorka známa Neapolskou tetralógiou.');
INSERT INTO genres (name, description) VALUES
                                           ('Fantasy', 'Žáner založený na magických a iných nadprirodzených formách.'),
                                           ('Sci-Fi', 'Žáner založený na predstavách budúcich vedeckých alebo technologických pokrokoch a ich vplyve na spoločnosť.'),
                                           ('Detektívka', 'Žáner zameraný na vyšetrovanie zločinov a odhaľovanie páchateľov.'),
                                           ('Romance', 'Romantické príbehy zamerané na vzťahy, lásku a emócie medzi postavami.'),
                                           ('Thriller', 'Napínavé príbehy plné zvratov, nebezpečenstva a psychologického napätia.'),
                                           ('Horror', 'Hororové príbehy zamerané na strach, nadprirodzené javy a temnú atmosféru.'),
                                           ('Historical', 'Príbehy zasadené do minulosti, často založené na historických udalostiach.'),
                                           ('Drama', 'Príbehy zamerané na medziľudské vzťahy, konflikty a emocionálny vývoj postáv.'),
                                           ('Adventure', 'Dobrodružné príbehy plné akcie, objavovania a nebezpečných výprav.');
